#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Balabit Stage 3: Genuine/Impostor Claims and Classical Baselines
================================================================

Input: Stage 2 output folder containing:
  - window_features/window_features_w*.csv.gz
  - feature_dictionary.csv
  - protocol_manifest.csv

Method:
  * User-specific verification (one-vs-rest claims).
  * Positive claims: windows generated by the claimed user.
  * Negative claims: balanced, stratified windows from other users.
  * Preprocessing is fitted on TRAIN rows only.
  * Decision threshold is selected on VALIDATION by minimum |FAR-FRR|.
  * The frozen threshold is evaluated once on INTERNAL TEST.

Outputs include per-user metrics, macro/pooled summaries, thresholds,
claim counts, prediction files for later statistical tests, and logs.
"""
from __future__ import annotations

import argparse
import gzip
import json
import logging
import math
import os
import platform
import re
import sys
import time
import zipfile
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Callable, Iterable, Optional

import numpy as np
import pandas as pd
from sklearn.ensemble import RandomForestClassifier
from sklearn.impute import SimpleImputer
from sklearn.metrics import (
    accuracy_score,
    confusion_matrix,
    f1_score,
    matthews_corrcoef,
    roc_auc_score,
    roc_curve,
)
from sklearn.preprocessing import StandardScaler
from sklearn.svm import LinearSVC, OneClassSVM, SVC

VERSION = "1.0.0"
EPS = 1e-12
MODEL_ORDER = ["centroid", "one_class_svm", "linear_svm", "random_forest", "rbf_svm"]
META_COLUMNS = {
    "dataset", "user_id", "session_id", "source_group", "protocol_split",
    "window_size", "stride", "window_index", "start_event_index",
    "end_event_index", "event_count", "start_time", "end_time",
}


def setup_logging(output: Path) -> logging.Logger:
    logger = logging.getLogger("balabit_stage3")
    logger.handlers.clear()
    logger.setLevel(logging.INFO)
    fmt = logging.Formatter("%(asctime)s | %(levelname)s | %(message)s")
    fh = logging.FileHandler(output / "run_log.txt", encoding="utf-8")
    fh.setFormatter(fmt)
    sh = logging.StreamHandler(sys.stdout)
    sh.setFormatter(fmt)
    logger.addHandler(fh)
    logger.addHandler(sh)
    return logger


def parse_csv_list(text: str) -> list[str]:
    return [x.strip() for x in text.split(",") if x.strip()]


def parse_sizes(text: str) -> list[int]:
    vals = sorted({int(x.strip()) for x in text.split(",") if x.strip()})
    if not vals or any(v < 5 for v in vals):
        raise argparse.ArgumentTypeError("Use comma-separated window sizes >= 5")
    return vals


def safe_auc(y_true: np.ndarray, scores: np.ndarray) -> float:
    try:
        return float(roc_auc_score(y_true, scores))
    except Exception:
        return float("nan")


def threshold_at_eer(y_true: np.ndarray, scores: np.ndarray) -> tuple[float, float, float, float]:
    """Return threshold, EER estimate, FAR, FRR on the supplied validation set."""
    y_true = np.asarray(y_true, dtype=int)
    scores = np.asarray(scores, dtype=float)
    if len(np.unique(y_true)) < 2:
        raise ValueError("Both genuine and impostor validation claims are required")
    fpr, tpr, thresholds = roc_curve(y_true, scores, pos_label=1)
    fnr = 1.0 - tpr
    idx = int(np.nanargmin(np.abs(fpr - fnr)))
    eer = float((fpr[idx] + fnr[idx]) / 2.0)
    return float(thresholds[idx]), eer, float(fpr[idx]), float(fnr[idx])


def classification_metrics(y_true: np.ndarray, scores: np.ndarray, threshold: float) -> dict[str, float | int]:
    y_true = np.asarray(y_true, dtype=int)
    scores = np.asarray(scores, dtype=float)
    pred = (scores >= threshold).astype(int)
    cm = confusion_matrix(y_true, pred, labels=[0, 1])
    tn, fp, fn, tp = [int(v) for v in cm.ravel()]
    far = fp / (fp + tn) if (fp + tn) else float("nan")
    frr = fn / (fn + tp) if (fn + tp) else float("nan")
    try:
        test_threshold, test_eer, _, _ = threshold_at_eer(y_true, scores)
    except Exception:
        test_threshold, test_eer = float("nan"), float("nan")
    return {
        "n_claims": int(len(y_true)),
        "genuine_claims": int(np.sum(y_true == 1)),
        "impostor_claims": int(np.sum(y_true == 0)),
        "tn": tn, "fp": fp, "fn": fn, "tp": tp,
        "accuracy": float(accuracy_score(y_true, pred)),
        "far": float(far),
        "frr": float(frr),
        "eer_test_curve": float(test_eer),
        "eer_test_threshold": float(test_threshold),
        "auc": safe_auc(y_true, scores),
        "f1": float(f1_score(y_true, pred, zero_division=0)),
        "mcc": float(matthews_corrcoef(y_true, pred)) if len(np.unique(y_true)) == 2 else float("nan"),
    }


def stratified_impostor_indices(
    users: np.ndarray,
    claimed_user: str,
    target_n: int,
    rng: np.random.Generator,
) -> np.ndarray:
    """Sample negatives approximately equally from each non-claimed user."""
    other_users = sorted(str(u) for u in np.unique(users) if str(u) != claimed_user)
    if target_n <= 0 or not other_users:
        return np.array([], dtype=np.int64)

    allocations = {u: target_n // len(other_users) for u in other_users}
    for u in other_users[: target_n % len(other_users)]:
        allocations[u] += 1

    selected: list[int] = []
    leftovers: list[int] = []
    for user in other_users:
        idx = np.flatnonzero(users.astype(str) == user)
        rng.shuffle(idx)
        take = min(len(idx), allocations[user])
        selected.extend(idx[:take].tolist())
        leftovers.extend(idx[take:].tolist())

    missing = target_n - len(selected)
    if missing > 0 and leftovers:
        leftovers_arr = np.asarray(leftovers, dtype=np.int64)
        rng.shuffle(leftovers_arr)
        selected.extend(leftovers_arr[:missing].tolist())
    return np.asarray(selected, dtype=np.int64)


def cap_indices(indices: np.ndarray, cap: int, rng: np.random.Generator) -> np.ndarray:
    if cap <= 0 or len(indices) <= cap:
        return indices
    result = indices.copy()
    rng.shuffle(result)
    return result[:cap]


def make_claim_set(
    X: np.ndarray,
    metadata: pd.DataFrame,
    claimed_user: str,
    negative_ratio: float,
    rng: np.random.Generator,
    positive_cap: int = 0,
    negative_cap: int = 0,
) -> tuple[np.ndarray, np.ndarray, pd.DataFrame]:
    users = metadata["user_id"].astype(str).to_numpy()
    pos_idx = np.flatnonzero(users == claimed_user)
    pos_idx = cap_indices(pos_idx, positive_cap, rng)
    target_neg = int(round(len(pos_idx) * negative_ratio))
    if negative_cap > 0:
        target_neg = min(target_neg, negative_cap)
    neg_idx = stratified_impostor_indices(users, claimed_user, target_neg, rng)
    all_idx = np.concatenate([pos_idx, neg_idx])
    y = np.concatenate([
        np.ones(len(pos_idx), dtype=np.int8),
        np.zeros(len(neg_idx), dtype=np.int8),
    ])
    order = np.arange(len(all_idx))
    rng.shuffle(order)
    all_idx = all_idx[order]
    y = y[order]
    meta = metadata.iloc[all_idx].copy().reset_index(drop=True)
    meta["claimed_user"] = claimed_user
    meta["label"] = y
    return X[all_idx], y, meta


@dataclass
class FittedScorer:
    name: str
    score_fn: Callable[[np.ndarray], np.ndarray]
    details: dict[str, Any]


def fit_scorer(
    model_name: str,
    X_train: np.ndarray,
    y_train: np.ndarray,
    X_positive_train: np.ndarray,
    seed: int,
    rf_trees: int,
    rf_max_depth: int,
    ocsvm_nu: float,
    rbf_c: float,
    rbf_gamma: str,
) -> FittedScorer:
    if model_name == "centroid":
        centroid = np.mean(X_positive_train, axis=0)
        def score_fn(X: np.ndarray) -> np.ndarray:
            return -np.linalg.norm(X - centroid, axis=1)
        return FittedScorer(model_name, score_fn, {"centroid_dimensions": int(len(centroid))})

    if model_name == "one_class_svm":
        model = OneClassSVM(kernel="rbf", gamma="scale", nu=ocsvm_nu, cache_size=2048)
        model.fit(X_positive_train)
        return FittedScorer(model_name, lambda X: model.decision_function(X).ravel(), {
            "nu": ocsvm_nu, "gamma": "scale", "positive_train_rows": int(len(X_positive_train))
        })

    if model_name == "linear_svm":
        model = LinearSVC(
            C=1.0,
            class_weight="balanced",
            dual=False,
            max_iter=10000,
            random_state=seed,
        )
        model.fit(X_train, y_train)
        return FittedScorer(model_name, lambda X: model.decision_function(X).ravel(), {
            "C": 1.0, "class_weight": "balanced"
        })

    if model_name == "random_forest":
        max_depth = None if rf_max_depth <= 0 else rf_max_depth
        model = RandomForestClassifier(
            n_estimators=rf_trees,
            max_depth=max_depth,
            min_samples_leaf=2,
            max_features="sqrt",
            class_weight="balanced_subsample",
            n_jobs=-1,
            random_state=seed,
        )
        model.fit(X_train, y_train)
        return FittedScorer(model_name, lambda X: model.predict_proba(X)[:, 1], {
            "n_estimators": rf_trees,
            "max_depth": max_depth,
            "min_samples_leaf": 2,
        })

    if model_name == "rbf_svm":
        model = SVC(
            kernel="rbf",
            C=rbf_c,
            gamma=rbf_gamma,
            class_weight="balanced",
            probability=False,
            cache_size=2048,
            random_state=seed,
        )
        model.fit(X_train, y_train)
        return FittedScorer(model_name, lambda X: model.decision_function(X).ravel(), {
            "C": rbf_c, "gamma": rbf_gamma, "class_weight": "balanced"
        })

    raise ValueError(f"Unknown model: {model_name}")


def measure_latency(score_fn: Callable[[np.ndarray], np.ndarray], X: np.ndarray, repeats: int = 5) -> tuple[float, float]:
    if len(X) == 0:
        return float("nan"), float("nan")
    sample = X[: min(len(X), 1000)]
    _ = score_fn(sample[: min(16, len(sample))])
    per_claim_ms: list[float] = []
    for _ in range(repeats):
        start = time.perf_counter()
        _ = score_fn(sample)
        elapsed = time.perf_counter() - start
        per_claim_ms.append((elapsed / len(sample)) * 1000.0)
    return float(np.mean(per_claim_ms)), float(np.percentile(per_claim_ms, 95))


def load_feature_names(stage2_dir: Path, df: pd.DataFrame) -> list[str]:
    dictionary = stage2_dir / "feature_dictionary.csv"
    if dictionary.exists():
        fdf = pd.read_csv(dictionary)
        candidates = [str(x) for x in fdf.get("feature", pd.Series(dtype=str)).dropna()]
        features = [c for c in candidates if c in df.columns]
    else:
        features = []
    # Include any numeric derived feature not explicitly listed, such as click_event_count.
    extra = [
        c for c in df.columns
        if c not in META_COLUMNS and c not in features and pd.api.types.is_numeric_dtype(df[c])
    ]
    features.extend(extra)
    # Stable unique order.
    return list(dict.fromkeys(features))


def audit_protocol(df: pd.DataFrame, window_size: int) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    required = {"user_id", "session_id", "protocol_split", "window_size"}
    missing = sorted(required - set(df.columns))
    rows.append({
        "window_size": window_size,
        "check": "required_columns",
        "status": "PASS" if not missing else "FAIL",
        "details": "all present" if not missing else f"missing={missing}",
    })
    if missing:
        return rows
    leakage = df.groupby(["user_id", "session_id"])["protocol_split"].nunique()
    bad = int((leakage > 1).sum())
    rows.append({
        "window_size": window_size,
        "check": "session_split_leakage",
        "status": "PASS" if bad == 0 else "FAIL",
        "details": f"sessions_in_multiple_splits={bad}",
    })
    split_users = df.groupby("protocol_split")["user_id"].nunique().to_dict()
    rows.append({
        "window_size": window_size,
        "check": "users_per_split",
        "status": "PASS" if all(split_users.get(s, 0) >= 2 for s in ["train", "validation", "internal_test"]) else "WARN",
        "details": json.dumps(split_users, ensure_ascii=False),
    })
    return rows


def append_gzip_csv(df: pd.DataFrame, path: Path, first_write: bool) -> None:
    mode = "wt" if first_write else "at"
    with gzip.open(path, mode, encoding="utf-8", newline="") as fh:
        df.to_csv(fh, index=False, header=first_write, lineterminator="\n")


def pooled_metrics(pred_df: pd.DataFrame) -> pd.DataFrame:
    rows: list[dict[str, Any]] = []
    if pred_df.empty:
        return pd.DataFrame()
    for (ws, model), g in pred_df.groupby(["window_size", "model"], sort=True):
        m = classification_metrics(g["label"].to_numpy(), g["score"].to_numpy(), 0.5)
        # pred has already been generated using each user's validation threshold.
        y = g["label"].to_numpy(dtype=int)
        p = g["prediction"].to_numpy(dtype=int)
        tn, fp, fn, tp = confusion_matrix(y, p, labels=[0, 1]).ravel()
        rows.append({
            "window_size": int(ws), "model": model,
            "n_claims": int(len(g)), "genuine_claims": int((y == 1).sum()), "impostor_claims": int((y == 0).sum()),
            "tn": int(tn), "fp": int(fp), "fn": int(fn), "tp": int(tp),
            "accuracy": float(accuracy_score(y, p)),
            "far": float(fp / (fp + tn)) if (fp + tn) else float("nan"),
            "frr": float(fn / (fn + tp)) if (fn + tp) else float("nan"),
            "auc": safe_auc(y, g["score"].to_numpy()),
            "f1": float(f1_score(y, p, zero_division=0)),
            "mcc": float(matthews_corrcoef(y, p)),
            "eer_test_curve": m["eer_test_curve"],
        })
    return pd.DataFrame(rows)


def zip_output(output: Path) -> Path:
    target = output.with_suffix(".zip")
    if target.exists():
        target.unlink()
    with zipfile.ZipFile(target, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        for p in sorted(output.rglob("*")):
            if p.is_file():
                compression = zipfile.ZIP_STORED if p.suffix == ".gz" else zipfile.ZIP_DEFLATED
                zf.write(p, arcname=p.relative_to(output.parent), compress_type=compression)
    return target


def parse_args() -> argparse.Namespace:
    ap = argparse.ArgumentParser(description="Balabit Stage 3 genuine/impostor claims and baselines")
    ap.add_argument("--stage2-dir", required=True, type=Path, help="Stage 2 results folder")
    ap.add_argument("--output", type=Path, default=Path("balabit_stage3_results"))
    ap.add_argument("--window-sizes", type=parse_sizes, default=[30, 50, 70, 90])
    ap.add_argument("--models", type=parse_csv_list, default=["centroid", "one_class_svm", "linear_svm", "random_forest"])
    ap.add_argument("--negative-ratio", type=float, default=1.0)
    ap.add_argument("--max-users", type=int, default=0, help="0 means all claimed users")
    ap.add_argument("--max-train-positive", type=int, default=5000)
    ap.add_argument("--max-train-negative", type=int, default=5000)
    ap.add_argument("--max-validation-positive", type=int, default=0)
    ap.add_argument("--max-test-positive", type=int, default=0)
    ap.add_argument("--ocsvm-max-positive", type=int, default=3000)
    ap.add_argument("--ocsvm-nu", type=float, default=0.05)
    ap.add_argument("--rf-trees", type=int, default=150)
    ap.add_argument("--rf-max-depth", type=int, default=20, help="<=0 means None")
    ap.add_argument("--rbf-c", type=float, default=10.0)
    ap.add_argument("--rbf-gamma", default="scale")
    ap.add_argument("--seed", type=int, default=42)
    ap.add_argument("--save-predictions", action="store_true")
    return ap.parse_args()


def main() -> int:
    args = parse_args()
    stage2_dir = args.stage2_dir.expanduser().resolve()
    output = args.output.expanduser().resolve()
    output.mkdir(parents=True, exist_ok=True)
    logger = setup_logging(output)
    started = time.time()

    logger.info("Balabit Stage 3 v%s", VERSION)
    logger.info("Stage 2 directory: %s", stage2_dir)
    logger.info("Window sizes: %s", args.window_sizes)
    logger.info("Models: %s", args.models)

    if not stage2_dir.is_dir():
        logger.error("Stage 2 directory does not exist: %s", stage2_dir)
        return 2
    unknown_models = sorted(set(args.models) - set(MODEL_ORDER))
    if unknown_models:
        logger.error("Unknown models: %s", unknown_models)
        return 2
    if args.negative_ratio <= 0:
        logger.error("negative-ratio must be > 0")
        return 2

    metrics_rows: list[dict[str, Any]] = []
    threshold_rows: list[dict[str, Any]] = []
    claim_rows: list[dict[str, Any]] = []
    audit_rows: list[dict[str, Any]] = []
    error_rows: list[dict[str, Any]] = []
    all_predictions: list[pd.DataFrame] = []
    feature_records: list[dict[str, Any]] = []

    for ws in args.window_sizes:
        feature_path = stage2_dir / "window_features" / f"window_features_w{ws}.csv.gz"
        if not feature_path.exists():
            error_rows.append({"window_size": ws, "claimed_user": "<all>", "model": "<load>", "error": f"Missing {feature_path}"})
            logger.error("Missing window file: %s", feature_path)
            continue

        logger.info("Loading window size %d from %s", ws, feature_path)
        df = pd.read_csv(feature_path, compression="gzip", low_memory=False)
        audit_rows.extend(audit_protocol(df, ws))
        if any(r["window_size"] == ws and r["status"] == "FAIL" for r in audit_rows):
            logger.error("Protocol audit failed for window size %d", ws)
            continue

        feature_names = load_feature_names(stage2_dir, df)
        if not feature_names:
            logger.error("No numeric features found for window size %d", ws)
            continue
        for name in feature_names:
            feature_records.append({"window_size": ws, "feature": name})
        logger.info("Window size %d: rows=%d features=%d", ws, len(df), len(feature_names))

        for col in feature_names:
            df[col] = pd.to_numeric(df[col], errors="coerce").replace([np.inf, -np.inf], np.nan)

        split_frames: dict[str, pd.DataFrame] = {}
        for split in ["train", "validation", "internal_test"]:
            sdf = df[df["protocol_split"] == split].copy().reset_index(drop=True)
            if sdf.empty:
                logger.error("No rows for split=%s window=%d", split, ws)
            split_frames[split] = sdf
        if any(split_frames[s].empty for s in split_frames):
            continue

        # Fit preprocessing on TRAIN ONLY.
        imputer = SimpleImputer(strategy="median")
        scaler = StandardScaler()
        X_train_raw = split_frames["train"][feature_names].to_numpy(dtype=np.float64)
        X_train_imp = imputer.fit_transform(X_train_raw)
        X_train = scaler.fit_transform(X_train_imp).astype(np.float32)
        X_val = scaler.transform(imputer.transform(split_frames["validation"][feature_names].to_numpy(dtype=np.float64))).astype(np.float32)
        X_test = scaler.transform(imputer.transform(split_frames["internal_test"][feature_names].to_numpy(dtype=np.float64))).astype(np.float32)
        X_by_split = {"train": X_train, "validation": X_val, "internal_test": X_test}

        users = sorted(split_frames["train"]["user_id"].astype(str).unique())
        if args.max_users > 0:
            users = users[: args.max_users]
        logger.info("Claimed users for window %d: %s", ws, users)

        for user_idx, claimed_user in enumerate(users):
            user_seed = args.seed + ws * 1000 + user_idx * 37
            try:
                train_rng = np.random.default_rng(user_seed + 1)
                val_rng = np.random.default_rng(user_seed + 2)
                test_rng = np.random.default_rng(user_seed + 3)
                Xtr, ytr, mtr = make_claim_set(
                    X_train, split_frames["train"], claimed_user, args.negative_ratio, train_rng,
                    positive_cap=args.max_train_positive, negative_cap=args.max_train_negative,
                )
                Xva, yva, mva = make_claim_set(
                    X_val, split_frames["validation"], claimed_user, args.negative_ratio, val_rng,
                    positive_cap=args.max_validation_positive, negative_cap=0,
                )
                Xte, yte, mte = make_claim_set(
                    X_test, split_frames["internal_test"], claimed_user, args.negative_ratio, test_rng,
                    positive_cap=args.max_test_positive, negative_cap=0,
                )
                if len(np.unique(ytr)) < 2 or len(np.unique(yva)) < 2 or len(np.unique(yte)) < 2:
                    raise ValueError("Each split must contain both genuine and impostor claims")

                claim_rows.extend([
                    {"window_size": ws, "claimed_user": claimed_user, "split": "train", "claims": len(ytr), "genuine": int((ytr == 1).sum()), "impostor": int((ytr == 0).sum())},
                    {"window_size": ws, "claimed_user": claimed_user, "split": "validation", "claims": len(yva), "genuine": int((yva == 1).sum()), "impostor": int((yva == 0).sum())},
                    {"window_size": ws, "claimed_user": claimed_user, "split": "internal_test", "claims": len(yte), "genuine": int((yte == 1).sum()), "impostor": int((yte == 0).sum())},
                ])

                positive_train = Xtr[ytr == 1]
                oc_rng = np.random.default_rng(user_seed + 4)
                oc_idx = cap_indices(np.arange(len(positive_train)), args.ocsvm_max_positive, oc_rng)
                positive_train_capped = positive_train[oc_idx]

                genuine_test_durations = pd.to_numeric(
                    mte.loc[mte["label"] == 1, "window_duration"], errors="coerce"
                ).dropna()
                median_collection_sec = float(genuine_test_durations.median()) if not genuine_test_durations.empty else float("nan")

                for model_name in [m for m in MODEL_ORDER if m in args.models]:
                    model_started = time.time()
                    try:
                        scorer = fit_scorer(
                            model_name, Xtr, ytr, positive_train_capped,
                            seed=user_seed,
                            rf_trees=args.rf_trees,
                            rf_max_depth=args.rf_max_depth,
                            ocsvm_nu=args.ocsvm_nu,
                            rbf_c=args.rbf_c,
                            rbf_gamma=args.rbf_gamma,
                        )
                        val_scores = scorer.score_fn(Xva)
                        threshold, val_eer, val_far, val_frr = threshold_at_eer(yva, val_scores)
                        test_scores = scorer.score_fn(Xte)
                        test_metrics = classification_metrics(yte, test_scores, threshold)
                        mean_latency_ms, p95_latency_ms = measure_latency(scorer.score_fn, Xte)
                        tta_seconds = median_collection_sec + mean_latency_ms / 1000.0 if np.isfinite(median_collection_sec) else float("nan")
                        pred = (test_scores >= threshold).astype(np.int8)

                        metrics_rows.append({
                            "window_size": ws,
                            "claimed_user": claimed_user,
                            "model": model_name,
                            "threshold_from_validation": threshold,
                            "validation_eer": val_eer,
                            "validation_far_at_threshold": val_far,
                            "validation_frr_at_threshold": val_frr,
                            **test_metrics,
                            "mean_inference_ms_per_claim": mean_latency_ms,
                            "p95_inference_ms_per_claim": p95_latency_ms,
                            "median_window_collection_seconds": median_collection_sec,
                            "tta_seconds": tta_seconds,
                            "fit_seconds": round(time.time() - model_started, 4),
                        })
                        threshold_rows.append({
                            "window_size": ws,
                            "claimed_user": claimed_user,
                            "model": model_name,
                            "threshold": threshold,
                            "selection_rule": "minimum absolute difference between FAR and FRR on validation",
                            "validation_eer": val_eer,
                            "validation_far": val_far,
                            "validation_frr": val_frr,
                            "model_details": json.dumps(scorer.details, ensure_ascii=False),
                        })

                        if args.save_predictions:
                            pdf = mte[["user_id", "session_id", "window_index", "window_duration", "claimed_user", "label"]].copy()
                            pdf.insert(0, "window_size", ws)
                            pdf.insert(1, "model", model_name)
                            pdf["score"] = test_scores
                            pdf["threshold"] = threshold
                            pdf["prediction"] = pred
                            all_predictions.append(pdf)

                        logger.info(
                            "w=%d user=%s model=%s EER=%.4f FAR=%.4f FRR=%.4f MCC=%.4f",
                            ws, claimed_user, model_name,
                            test_metrics["eer_test_curve"], test_metrics["far"],
                            test_metrics["frr"], test_metrics["mcc"],
                        )
                    except Exception as exc:
                        logger.exception("Model failed w=%d user=%s model=%s", ws, claimed_user, model_name)
                        error_rows.append({"window_size": ws, "claimed_user": claimed_user, "model": model_name, "error": f"{type(exc).__name__}: {exc}"})
            except Exception as exc:
                logger.exception("Claim construction failed w=%d user=%s", ws, claimed_user)
                error_rows.append({"window_size": ws, "claimed_user": claimed_user, "model": "<claims>", "error": f"{type(exc).__name__}: {exc}"})

        del df, X_train_raw, X_train_imp, X_train, X_val, X_test, X_by_split

    metrics_df = pd.DataFrame(metrics_rows)
    thresholds_df = pd.DataFrame(threshold_rows)
    claims_df = pd.DataFrame(claim_rows)
    audit_df = pd.DataFrame(audit_rows)
    errors_df = pd.DataFrame(error_rows, columns=["window_size", "claimed_user", "model", "error"])
    features_df = pd.DataFrame(feature_records).drop_duplicates()

    metrics_df.to_csv(output / "metrics_by_user.csv", index=False, encoding="utf-8-sig")
    thresholds_df.to_csv(output / "thresholds.csv", index=False, encoding="utf-8-sig")
    claims_df.to_csv(output / "claim_counts.csv", index=False, encoding="utf-8-sig")
    audit_df.to_csv(output / "protocol_audit.csv", index=False, encoding="utf-8-sig")
    errors_df.to_csv(output / "stage3_errors.csv", index=False, encoding="utf-8-sig")
    features_df.to_csv(output / "features_used.csv", index=False, encoding="utf-8-sig")

    predictions_df = pd.concat(all_predictions, ignore_index=True) if all_predictions else pd.DataFrame()
    if args.save_predictions and not predictions_df.empty:
        predictions_df.to_csv(output / "test_predictions.csv.gz", index=False, compression="gzip")

    if not metrics_df.empty:
        metric_cols = [
            "accuracy", "far", "frr", "eer_test_curve", "auc", "f1", "mcc",
            "validation_eer", "mean_inference_ms_per_claim", "p95_inference_ms_per_claim",
            "median_window_collection_seconds", "tta_seconds", "fit_seconds",
        ]
        agg_parts = []
        for (ws, model), g in metrics_df.groupby(["window_size", "model"], sort=True):
            row: dict[str, Any] = {"window_size": ws, "model": model, "users": int(g["claimed_user"].nunique())}
            for col in metric_cols:
                row[f"{col}_mean"] = float(pd.to_numeric(g[col], errors="coerce").mean())
                row[f"{col}_std"] = float(pd.to_numeric(g[col], errors="coerce").std(ddof=1))
                row[f"{col}_min"] = float(pd.to_numeric(g[col], errors="coerce").min())
                row[f"{col}_max"] = float(pd.to_numeric(g[col], errors="coerce").max())
            agg_parts.append(row)
        macro_df = pd.DataFrame(agg_parts)
        macro_df.to_csv(output / "metrics_macro.csv", index=False, encoding="utf-8-sig")

        ranking = macro_df.sort_values(
            ["eer_test_curve_mean", "far_mean", "mcc_mean", "tta_seconds_mean"],
            ascending=[True, True, False, True],
        ).copy()
        ranking.insert(0, "overall_rank", np.arange(1, len(ranking) + 1))
        ranking.to_csv(output / "window_model_ranking.csv", index=False, encoding="utf-8-sig")
    else:
        macro_df = pd.DataFrame()
        ranking = pd.DataFrame()

    if not predictions_df.empty:
        pooled_df = pooled_metrics(predictions_df)
        pooled_df.to_csv(output / "metrics_pooled.csv", index=False, encoding="utf-8-sig")
    else:
        pooled_df = pd.DataFrame()

    summary = {
        "stage": "Balabit Stage 3 - genuine/impostor claims and classical baselines",
        "version": VERSION,
        "generated_at_utc": datetime.now(timezone.utc).isoformat(),
        "stage2_dir": str(stage2_dir),
        "window_sizes_requested": args.window_sizes,
        "models_requested": args.models,
        "negative_ratio": args.negative_ratio,
        "seed": args.seed,
        "max_users": args.max_users,
        "max_train_positive": args.max_train_positive,
        "max_train_negative": args.max_train_negative,
        "ocsvm_max_positive": args.ocsvm_max_positive,
        "rf_trees": args.rf_trees,
        "rf_max_depth": args.rf_max_depth,
        "metrics_rows": int(len(metrics_df)),
        "threshold_rows": int(len(thresholds_df)),
        "prediction_rows": int(len(predictions_df)),
        "errors": int(len(errors_df)),
        "elapsed_seconds": round(time.time() - started, 3),
        "methodological_notes": [
            "Verification is user-specific: each claimed user has genuine and impostor claims.",
            "Impostor windows are sampled approximately equally across other users.",
            "Imputer and StandardScaler are fitted only on Stage 2 training windows.",
            "Thresholds are selected only on validation by the EER crossing rule and frozen for test.",
            "Internal test sessions are never used for fitting, scaling, or threshold selection.",
            "Session-level split inherited from Stage 2 prevents overlapping-window leakage across splits.",
            "RBF SVM is optional because its computational cost is high on large claim sets.",
        ],
    }
    with (output / "stage3_summary.json").open("w", encoding="utf-8") as fh:
        json.dump(summary, fh, ensure_ascii=False, indent=2)

    zip_path = zip_output(output)
    logger.info("Completed metrics=%d errors=%d", len(metrics_df), len(errors_df))
    logger.info("ZIP: %s", zip_path)
    print("\nRESULT_ZIP=" + str(zip_path))
    return 0 if errors_df.empty else 5


if __name__ == "__main__":
    raise SystemExit(main())
